const sum = weights.reduce((a, b) => a + b, 0);
const shares = weights.map((w) => Math.floor((totalCents * w) / sum));
let remainder = totalCents - shares.reduce((a, b) => a + b, 0);
for (let i = 0; remainder > 0 && i < shares.length; i++) {
  if (weights[i] > 0) {
    shares[i]++;
    remainder--;
  }
}
return shares;

